/*
 * approx_exp_avx2.h - AVX2 binary64 exp(-a) kernels (opt-in
 * AVX2_EXP path) + the AUTO-GENERATED float-exp constants used by
 * that path.
 *
 * Three width variants for the microarchitecture sweep (speed_exp_avx2.c);
 * all compute the SAME exp(-a) (degree-6 minimax, B=8 range reduction),
 * differing only in how many independent __m256d Horner chains run
 * concurrently: W4 (1 stream) / W8 (2) / W16 (4 -- the production width,
 * matching the GAUSS_BATCH mini-batch).  More streams hide the ~4-cycle
 * FMA latency by filling the two FMA ports.
 *
 * Inputs/outputs are plain double arrays of the stated width.  These are
 * the RAW exp(-a) kernels (double in, double out); approx_exp_avx2() wraps
 * the chosen width with the Q60->double and exp->Q63 conversions for the
 * sampler.
 *
 * The constants block below is generated by
 * tools/avxexp/gen_avxexp_consts.py (reproducible-constants gate `make
 * check-consts`); do NOT edit between the
 * @@AUTOGEN markers.
 */
#ifndef LITHIUM_APPROX_EXP_AVX2_H
#define LITHIUM_APPROX_EXP_AVX2_H

#include <stdint.h>

/* @@AUTOGEN:approx_exp_avx2@@ BEGIN */
/* Float exp(-a) constants (binary64) for the AVX2 sampler exp.
 * C[i]: degree-6 minimax of exp on [7/8 ln2, ln2) (Sollya fpminimax,
 *       logged under tools/avxexp/LogAVXApprox/).
 * T[j]: 2^{-j/8}, j=0..7 (closed form).
 * Validated: max rel error over [0,7.369] = 2^-49.04 (gate 2^-43). */
/* range reduction: B-entry table, degree-DEG Horner.  m=ceil(a*INV)+(B-1),
 * n=m>>LOG2B, j=m&(B-1), r_l=m*LB-a; exp(-a)=2^-n * 2^{-j/B} * P(r_l). */
#define APPROX_EXP_AVX2_B 8
#define APPROX_EXP_AVX2_LOG2B 3
#define APPROX_EXP_AVX2_DEG 6
#define APPROX_EXP_AVX2_LN2 \
    0.6931471805599453 /* hex 0x1.62e42fefa39efp-1 */
#define APPROX_EXP_AVX2_INV \
    11.541560327111707 /* hex 0x1.71547652b82fep+3  (B/ln2) */
#define APPROX_EXP_AVX2_LB \
    0.08664339756999316 /* hex 0x1.62e42fefa39efp-4  (ln2/B) */
#define APPROX_EXP_AVX2_SCALE63 9223372036854775808.0 /* 2^63 */

static const double APPROX_EXP_AVX2_C[7] = {
    1.000017029688622 /* hex 0x1.00011db5f4a84p+0 */,
    0.9998181124150078 /* hex 0x1.ffe828dd8ab4cp-1 */,
    0.5008292820587139 /* hex 0x1.006cb216a4862p-1 */,
    0.16457890339420803 /* hex 0x1.510ebe7d84701p-3 */,
    0.044787736908069656 /* hex 0x1.6ee6b129063cap-5 */,
    0.00559066059537778 /* hex 0x1.6e63b86b91249p-8 */,
    0.0026598531260834946 /* hex 0x1.5ca1dc609c3c0p-9 */,
};

static const double APPROX_EXP_AVX2_T[8] = {
    1.0 /* 2^-0/8  hex 0x1.0000000000000p+0 */,
    0.9170040432046712 /* 2^-1/8  hex 0x1.d5818dcfba487p-1 */,
    0.8408964152537145 /* 2^-2/8  hex 0x1.ae89f995ad3adp-1 */,
    0.7711054127039704 /* 2^-3/8  hex 0x1.8ace5422aa0dbp-1 */,
    0.7071067811865476 /* 2^-4/8  hex 0x1.6a09e667f3bcdp-1 */,
    0.6484197773255048 /* 2^-5/8  hex 0x1.4bfdad5362a27p-1 */,
    0.5946035575013605 /* 2^-6/8  hex 0x1.306fe0a31b715p-1 */,
    0.5452538663326288 /* 2^-7/8  hex 0x1.172b83c7d517bp-1 */,
};
/* @@AUTOGEN:approx_exp_avx2@@ END */

void exp_avx2_w4(const double *a, double *out);  /* 4  in/out */
void exp_avx2_w8(const double *a, double *out);  /* 8  in/out */
void exp_avx2_w16(const double *a, double *out); /* 16 in/out */

/* Production wrapper used by exp_batch() when AVX2_EXP is enabled:
 * input is Q60, output is Q63 for the integer rejection comparison. */
void approx_exp_avx2(uint64_t *expv, const uint64_t *a_q60, int n);

#endif /* LITHIUM_APPROX_EXP_AVX2_H */
